createFaultFunction:
CREATE FUNCTION os_rr_fault_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF NEW.org_id<>TG_ARGV[0] THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME IN ('os_records','os_reports') THEN IF NEW.id<>TG_ARGV[1] THEN RETURN NEW; END IF;
 ELSIF TG_TABLE_NAME='os_events' THEN IF NEW.action<>TG_ARGV[1] OR (TG_ARGV[2]<>'' AND NEW.record_id IS DISTINCT FROM TG_ARGV[2]) THEN RETURN NEW; END IF;
 ELSIF TG_TABLE_NAME='os_previews' THEN IF NEW.id<>TG_ARGV[1] OR OLD.payload->>'format'<>'charitology-participation-recurrence-preview' OR NEW.payload->>'format'<>'charitology-participation-recurrence-receipt' THEN RETURN NEW; END IF;
 ELSE RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='fictional recurrence fixed fixture'; END IF;
 PERFORM nextval('os_rr_fault_seq');
 RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='fictional recurrence fixed fixture';
END; $$;

createBallastFunction:
CREATE FUNCTION os_rr_ballast_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE measured bigint;
BEGIN
 IF NEW.org_id IS DISTINCT FROM 'rr_quota' OR NEW.kind IS DISTINCT FROM 'participation-recurrence-v1' OR OLD.committed_at IS NOT NULL OR NEW.committed_at IS NULL OR NEW.payload->>'format' IS DISTINCT FROM 'charitology-participation-recurrence-receipt' THEN RETURN NEW; END IF;
 INSERT INTO os_reports(org_id,id,created_by,title,checksum,payload) VALUES(NEW.org_id,'rr-quota-ballast',NEW.actor_id,'Fictional counterfactual quota stimulus',repeat('0',64),jsonb_build_object('fictionalCounterfactualBallast',repeat('x',61*1024*1024)));
 SELECT octet_length(to_jsonb(t)::text)::bigint INTO STRICT measured FROM os_reports t WHERE org_id='rr_quota' AND id='rr-quota-ballast';
 PERFORM nextval('os_rr_ballast_fired'); PERFORM setval('os_rr_ballast_bytes',measured,true); RETURN NEW;
END; $$;
